Then('all todos are completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    expect(item.classList.contains('completed')).to.be.true;
  }
});

Then('all todos are not completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    expect(item.classList.contains('completed')).to.be.false;
  }
});

Then('the {string} button is hidden', function (buttonName) {
  const selectors = {
    'Clear completed': '.clear-completed'
  };
  const el = this.document.querySelector(selectors[buttonName]);
  if (el) {
